files.content:
:root {
  --card-height: 65vh;
}

@property --rotate {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

@keyframes spin {
  0% {
    --rotate: 0deg;
  }

  100% {
    --rotate: 360deg;
  }
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  background-color: #000;
}

.card {
  position: relative;
  block-size: var(--card-height);
  border-radius: 6px;
  background: #191c29;
  background-image: url(../images/akopyan.jpg);
  background-position: center;
  background-size: cover;
  aspect-ratio: 2 / 3;
}

.card::before {
  animation: spin 3s linear infinite;
  content: '';
  position: absolute;
  z-index: -1;
  inline-size: 104%;
  block-size: 102.5%;
  border-radius: 8px;
  background-image:
    linear-gradient(
      var(--rotate, 132deg)
      , #5ddcff, #3c67e3 43%, #4e00c2);
  inset-block-start: -1%;
  inset-inline-end: -2%;
}

.card::after {
  content: '';
  position: absolute;
  z-index: -1;
  inline-size: 100%;
  block-size: 100%;
  margin-inline: auto;
  margin-block: 0;
  background-image:
    linear-gradient(
      132deg
      , #5ddcff, #3c67e3 43%, #4e00c2);
  filter: blur(calc(var(--card-height) / 6));
  transform: scale(0.8);
  inset-block-start: calc(var(--card-height) / 6);
  inset-inline-end: 0;
}
